"""Versioned documentation-backed mappings; this is the runtime mapping audit."""
import json
from pathlib import Path
H=Path(__file__).resolve().parent
REFS={
 'CID_SID':'https://support.nlm.nih.gov/knowledgebase/article/KA-03387/en-us',
 'COMPOUNDS':'https://pubchem.ncbi.nlm.nih.gov/docs/compounds',
 'SUBSTANCES':'https://pubchem.ncbi.nlm.nih.gov/docs/substances',
 'PUG_REST':'https://pubchem.ncbi.nlm.nih.gov/docs/pug-rest',
 'DATA_SOURCES':'https://pubchem.ncbi.nlm.nih.gov/docs/data-sources',
 'COMPUTED':'https://pubchem.ncbi.nlm.nih.gov/docs/rdf-compound',
 'GLOSSARY':'https://pubchem.ncbi.nlm.nih.gov/docs/glossary',
 'SYNONYM_FILTER':'https://pmc.ncbi.nlm.nih.gov/articles/PMC11181558/',
 'STANDARDIZATION':'https://pmc.ncbi.nlm.nih.gov/articles/PMC6086778/',
 'ASN':'https://www.ncbi.nlm.nih.gov/IEB/ToolBox/CPP_DOC/asn_spec/pcsubstance.asn.html',
 'CHEBI':'https://www.ebi.ac.uk/chebi/downloads'}
def main():
 fields=[]
 def add(name,path,definition,origin,record,role,binding,dims,dependencies,limits,refs,available):
  fields.append(dict(field=name,payload_path=path,definition=definition,contributor_or_derivation=origin,record_semantics=record,claim_role=role,binding_policy=binding,supportable_dimensions=dims,cannot_establish='Exact canonical Substance, source name specificity, original form preservation or independent corroboration unless separately established',dependencies=dependencies,limitations=limits,documentation=[REFS[x] for x in refs],local_availability=available,mapping_version='1.0'))
 dims=['constitution','stereochemistry','tautomer','protonation_charge','isotope','components','component_stoichiometry','hydration_solvation','electronic_state']
 add('CID','$.PropertyTable.Properties[].CID -> cached $.rows[].CID','Compound accession','Assigned by PubChem','standardized Compound','REFERENCE_CROSS_LINK','NONBINDING_ASSOCIATION',[],[],'Links database record only; not ontology Substance; positive integer required',['CID_SID','PUG_REST'],'AVAILABLE')
 add('SMILES / IsomericSMILES','$.PropertyTable.Properties[].SMILES or IsomericSMILES -> cached $.rows[]','Isomeric structure serialization of standardized Compound','Computed descriptor from standardized graph; per-record generator absent','standardized Compound','STRUCTURAL_IDENTITY_ASSERTION','BINDING_IDENTITY_ASSERTION',dims,[],'Only represented graph; unspecified stereo remains unresolved; dot solvent not a physical hydrate assertion; original SID transformations unproven',['PUG_REST','COMPUTED','STANDARDIZATION'],'SMILES_AVAILABLE')
 add('ConnectivitySMILES / CanonicalSMILES','$.PropertyTable.Properties[].ConnectivitySMILES or CanonicalSMILES','Connectivity-only serialization','Computed from standardized graph','standardized Compound','STRUCTURAL_IDENTITY_ASSERTION','QUALIFIED_PARTIAL_ASSERTION',['constitution','components','component_stoichiometry'],['same Compound graph'],'Does not establish stereo, isotope, exact charge/H/tautomer or original form',['PUG_REST','GLOSSARY'],'NOT_PRESENT_IN_SELECTED_CACHE')
 add('InChI / InChIKey','$.PropertyTable.Properties[].InChI or InChIKey -> cached $.rows[]','Structure-derived Standard InChI representation or hash','Computed using InChI implementation; version unavailable here','standardized Compound','STRUCTURAL_IDENTIFIER','QUALIFIED_PARTIAL_ASSERTION',[],['same Compound graph'],'Recomputed equality supports Standard InChI projection consistency only; not exact tautomer/H or independent corroboration. Standalone parsed InChI adapter exposes constitution only. Hash without mapped graph stays unresolved.',['PUG_REST','COMPUTED','STANDARDIZATION'],'AVAILABLE')
 add('IUPACName','$.PropertyTable.Properties[].IUPACName -> cached $.rows[].IUPACName','Generated systematic name','Computed descriptor; no per-record generator/version in payload','standardized Compound','CHEMICAL_NAME_ASSERTION / PARTIAL_IDENTITY_ASSERTION','ACTIVE_UNRESOLVED_CLAIM / QUALIFIED_PARTIAL_ASSERTION',['constitution','protonation_charge'],['same Compound graph'],'Only existing NSC contracts can establish constitution; charge only from complete ChargeDimensionEvidence. Derived name is not independent verification.',['PUG_REST','GLOSSARY','SYNONYM_FILTER'],'AVAILABLE')
 add('Compound synonyms','$.InformationList.Information[].Synonym[]','Filtered name-structure associations aggregated from linked SID records','Depositor associations; individual depositor attribution absent in this response','Compound-associated terminology','REPORTED_NAME_ASSOCIATION','NONBINDING_ASSOCIATION',[],['linked SID associations and synonym filtering'],'Filtering seeks consensus, not correctness. Not metadata; active unresolved in terminology/matching scope. CAS-like string never validated by membership.',['SYNONYM_FILTER','CID_SID','PUG_REST'],'UNAVAILABLE_IN_SELECTED_PROPERTY_CACHE')
 add('SID','$.PC_Substances[].sid.id','Substance accession','Assigned by PubChem','depositor Substance','REFERENCE_CROSS_LINK','NONBINDING_ASSOCIATION',[],[],'SID is not CID or canonical Substance',['ASN','CID_SID'],'NO_RAW_SID_RECORDS')
 add('Depositor provenance','$.PC_Substances[].source.db.name / source_id','Depositor database and source accession','Depositor-level source metadata','depositor Substance','NONBINDING_METADATA','NONBINDING_ASSOCIATION',[],[],'Missing provenance retained as unavailable; never copied from CID context',['ASN','SUBSTANCES'],'NO_RAW_SID_RECORDS')
 add('SID synonyms','$.PC_Substances[].synonyms[]','Unfiltered depositor terminology','Specific depositor when source.db metadata supplied','depositor Substance','REPORTED_NAME_ASSOCIATION','NONBINDING_ASSOCIATION',[],['same SID depositor'],'Not verified exact aliases; remain unresolved terminology obligations',['ASN','SYNONYM_FILTER'],'NO_RAW_SID_RECORDS')
 add('SID compound payload / linked CID','$.PC_Substances[].compound[].id.id.cid','Source structural records and Compound linkage','Depositor payload and PubChem processing; classification requires raw structure metadata','depositor Substance and associated Compound','UNKNOWN_ROLE / REFERENCE_CROSS_LINK','ACTIVE_UNRESOLVED_CLAIM / NONBINDING_ASSOCIATION',[],['SID depositor source and standardization route'],'Raw atom/bond/stereo reconstruction deliberately unsupported; linkage is not original-form equivalence or independent SID corroboration',['ASN','SUBSTANCES','STANDARDIZATION'],'NO_RAW_SID_RECORDS')
 add('External identifiers / CAS-like strings','Identifier namespace-specific cross-reference or synonym field','Reported registry association','Source contributor when documented','association, not validated exact form','REFERENCE_CROSS_LINK / STRUCTURAL_IDENTIFIER','ACTIVE_UNRESOLVED_CLAIM',[],['auditable exact mapping route and explicit graph required'],'No actual independent external mapping established by property cache; typed mapping boundary tested on annotated controls only',['PUG_REST','SYNONYM_FILTER'],'NO_QUALIFIED_EXTERNAL_MAPPING')
 add('ChEBI default structure','$.data.default_structure.smiles / standard_inchi / standard_inchi_key','Represented ChEBI entity structure and computed serializations','ChEBI structure view; original contributor not assumed','chemical entity, not necessarily Substance','STRUCTURAL_IDENTITY_ASSERTION','BINDING_IDENTITY_ASSERTION',dims,['computed identifiers depend on graph'],'R-group structures unsupported; stars and release status preserved, not independent proof',['CHEBI'],'AVAILABLE')
 add('ChEBI terminology / references','$.data.name; $.data.names.<type>[]; $.data.database_accessions.<type>[]','Preferred name, sourced synonyms and cross-references','Retain per-name source/status/type and xref source_name','entity terminology','CHEMICAL_NAME_ASSERTION / REPORTED_NAME_ASSOCIATION / REFERENCE_CROSS_LINK','ACTIVE_UNRESOLVED_CLAIM / NONBINDING_ASSOCIATION',['constitution','protonation_charge'],['only existing semantic contracts where supported'],'Curation does not certify project granularity; no exact alias promotion or external identifier correspondence inferred',['CHEBI'],'AVAILABLE')
 roles={
 'STRUCTURAL_IDENTITY_ASSERTION':('Documented structural field, provenance, strict graph validation','Represented graph only','BINDING_IDENTITY_ASSERTION','Unknown graph attributes or invalid/unproven provenance remain unresolved'),
 'CHEMICAL_NAME_ASSERTION':('Documented chemical-name field','Potential chemical identity claim; interpretation required','ACTIVE_UNRESOLVED_CLAIM','Unsupported interpretation remains active, never inferred broad'),
 'PARTIAL_IDENTITY_ASSERTION':('Validated NSC/charge output with source span, rules and correspondence','Only explicitly supported dimensions','QUALIFIED_PARTIAL_ASSERTION','Operation success never establishes unsupported dimensions'),
 'REPORTED_NAME_ASSOCIATION':('Documented source synonym/name-association field','A reported link; not a verified exact molecular alias','NONBINDING_ASSOCIATION','Retained unresolved within terminology/incoming scope; not recast as metadata'),
 'UNVERIFIED_ALIAS':('Source asserts alias, no exact validation','Active unresolved asserted alias','ACTIVE_UNRESOLVED_CLAIM','Cannot enter persistent alias registry'),
 'STRUCTURAL_IDENTIFIER':('Documented identifier type, lineage, mapping route','Encoded projection or explicitly mapped dimensions only','QUALIFIED_PARTIAL_ASSERTION','Unmapped identifiers and contradictions remain unresolved/conflicting as supported'),
 'REFERENCE_CROSS_LINK':('Documented namespace and source field','Database-record reference only','NONBINDING_ASSOCIATION','External exact-form correspondence unavailable unless separately validated'),
 'NONBINDING_METADATA':('Documented descriptive/search/source metadata','No molecular identity dimensions','NONBINDING_ASSOCIATION','Unknown potentially identifying field never assigned this role'),
 'UNKNOWN_ROLE':('Field meaning/provenance insufficient','No supported identity assertion','ACTIVE_UNRESOLVED_CLAIM','Active in every scope until qualified')}
 policy={'version':'1.0','roles':{k:dict(required_source_evidence=v[0],chemical_implications=v[1],binding_policy=v[2],unresolved_conditions=v[3],participation='Explicit package scopes; lineage preserved; all claims retained',provenance_required=['source record type/ID','payload hash/path','field pointer','role rule version','dependencies']) for k,v in roles.items()},'scopes':{'RECORD_STRUCTURE':'Only represented graph and associated explicit structural consistency obligations; does not validate terminology or incoming concept','TERMINOLOGY':'Names/associations interpreted against represented graph; unsupported claims remain active. Exact incompatibilities retained. Completion limited to declared dimensions.','INCOMING_CONCEPT':'Requires independently established incoming-to-source correspondence; currently never established by record membership.'},'no_independence_vote':True,'synonym_alias_promotion':False,'core_changes':'NONE'}
 for name,obj in [('source_field_catalog.json',{'version':'1.0','documentation':REFS,'fields':fields,'review_status':'CHEMICAL_REVIEW_PENDING'}),('claim_role_policy.json',policy)]:
  (H/name).write_text(json.dumps(obj,indent=2)+'\n',encoding='utf8')
if __name__=='__main__':main()
